<?php
use EIPSI\StudyEngine\Persistence as P;
use EIPSI\StudyEngine\Privacy as G;
use EIPSI\StudyEngine\Longitudinal as L;
use EIPSI\StudyEngine\Contracts\Canonical;
pg_case('B2 clears partial answers without any final submission',function(){ $f=pf_enroll(pf_publish());$r=pe_request($f,'partial',array('R_q1'=>'private-partial'));pf_runtime()->handle($f['study']['public_id'],$f['token'],$r);pe_assert(strpos(pg_row($f)['checkpoint_json'],'private-partial')!==false,'No partial fixture');pe_assert(pg_export($f)['rows'][0]['response_status']==='PARTIAL_ANSWER','Partial reported as final');pg_withdraw(pg_shell($f),'DO_NOT_USE');$c=pg_cleanup($f);pe_assert($c['cleanup_state']==='COMPLETE_LOCAL'&&strpos(pg_row($f)['checkpoint_json'],'private-partial')===false,'Partial retained');});
pg_case('B2 local form events partial rows and device metadata are relationally deleted',function(){global $wpdb;$f=pg_complete(pf_enroll(pf_publish()));$id=$f['access']['execution_id'];$j=(new P\SubmissionJournalRepository(pf_db()))->list($id);preg_match('/([0-9]+)$/',$j[0]['local_storage_ref'],$m);$now=P\Database::now();pe_assert($wpdb->insert($wpdb->prefix.'vas_form_events',array('form_id'=>'PG_LOCAL','session_id'=>$id,'event_type'=>'test','metadata'=>'private-event','user_agent'=>'private-UA','created_at'=>$now))!==false,'Event fixture');pe_assert($wpdb->insert($wpdb->prefix.'eipsi_partial_responses',array('form_id'=>'PG_LOCAL','participant_id'=>$f['access']['participant_id'],'session_id'=>$id,'responses_json'=>'{"private":"partial"}','created_at'=>$now,'updated_at'=>$now))!==false,'Partial fixture');pe_assert($wpdb->insert($wpdb->prefix.'eipsi_device_data',array('submission_id'=>$m[1],'canvas_fingerprint'=>'private-device'))!==false,'Device fixture');pg_withdraw(pg_shell($f),'DO_NOT_USE');$c=pg_cleanup($f);pe_assert($c['cleanup_state']==='COMPLETE_LOCAL','Cleanup');foreach(array('vas_form_events','eipsi_partial_responses') as $t)pe_assert((int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM `'.$wpdb->prefix.$t.'` WHERE session_id=%s',$id))===0,'Retained '.$t);pe_assert((int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM `'.$wpdb->prefix.'eipsi_device_data` WHERE submission_id=%d',$m[1]))===0,'Device retained');});
pg_case('restricted sessions cannot enroll a new email to escape purpose',function(){ $f=pf_enroll(pf_publish());$s=pg_shell($f);pe_reject(function()use($s){pf_runtime()->handle($s['study']['public_id'],$s['token'],array('action'=>'enroll','command_id'=>'PURPOSE_ESCAPE','csrf'=>$s['csrf'],'email'=>'new-scope@example.test'));},'INVALID_SESSION_PURPOSE');});
pg_case('wrong Participant token cannot withdraw another execution',function(){ $p=pf_publish();$a=pf_enroll($p);$b=pg_shell(pf_enroll($p));pe_reject(function()use($a,$b,$p){pf_owner()->withdrawExecution($a['access']['execution_id'],'DO_NOT_USE','WRONG_PT',pg_row($a)['revision'],G\AccessContext::session(pf_db(),$p['public'],$b['token'],pf_clock()));},'INVALID_SESSION_PURPOSE');});
pg_case('expired withdrawal capability cannot create session or record',function(){ $f=pf_enroll(pf_publish());$cap=pf_mint($f,'WITHDRAWAL_OPTIONS');$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($old)+49*3600);try{pe_reject(function()use($f,$cap){pf_runtime()->redeem($f['study']['public_id'],$cap);},'ACCESS_REQUIRED');pe_assert(pg_count('withdrawal_records',$f)===0,'Expired mutated');}finally{$GLOBALS['pf_now']=$old;}});
pg_case('forged withdrawal capability signature rejects',function(){ $f=pf_enroll(pf_publish());$cap=pf_mint($f,'WITHDRAWAL_OPTIONS');$cap[strlen($cap)-1]=$cap[strlen($cap)-1]==='a'?'b':'a';pe_reject(function()use($f,$cap){pf_runtime()->redeem($f['study']['public_id'],$cap);},'ACCESS_REQUIRED');});
pg_case('B2 tombstone does not retain arm definitions or calendar occurrences',function(){ $f=pf_enroll(pf_publish('06'));pg_withdraw(pg_shell($f),'DO_NOT_USE');pg_cleanup($f);foreach(pf_db()->rows(pf_db()->prepare('SELECT definition_id,occurrence_json,snapshot_json FROM '.pf_db()->table('block_executions').' WHERE execution_id=%s',$f['access']['execution_id'])) as $b)pe_assert($b['definition_id']==='REDACTED'&&strpos($b['occurrence_json'],'slot')===false&&!isset(P\Database::json($b['snapshot_json'])['available_at']),'Scientific tombstone');});
pg_case('corrupt tombstone hash fails closed without scientific hydration',function(){ $f=pf_enroll(pf_publish());pg_withdraw(pg_shell($f),'DO_NOT_USE');pg_cleanup($f);pf_db()->transactional(function()use($f){pf_db()->update('study_executions',array('checkpoint_hash'=>str_repeat('0',64)),pf_db()->prepare('id=%s',$f['access']['execution_id']));});pe_assert(pf_owner()->view($f['access']['execution_id'])['next_action']['kind']==='OPERATIONAL_ERROR','Corruption accepted');});
pg_case('ambiguous Storage reference fails cleanup instead of deleting another owner row',function(){ $a=pg_complete(pf_enroll(pf_publish()));$b=pg_complete(pf_enroll(pf_publish()));$ref=(new P\SubmissionJournalRepository(pf_db()))->list($b['access']['execution_id'])[0]['local_storage_ref'];pg_withdraw(pg_shell($a),'DO_NOT_USE');pf_db()->transactional(function()use($a,$ref){pf_db()->update('submission_journal',array('local_storage_ref'=>$ref),pf_db()->prepare('execution_id=%s',$a['access']['execution_id']));});$r=pg_cleanup($a);pe_assert($r['cleanup_state']==='FAILED'&&pg_export($a)['rows']===array()&&pg_export($b)['rows'][0]['value']==='previous-answer','Ambiguous deletion');});
pg_case('nontransactional queue refuses initial withdrawal with full rollback',function(){global $wpdb;$f=pf_enroll(pf_publish());$s=pg_shell($f);$before=pg_row($f);$wpdb->query('ALTER TABLE `'.$wpdb->prefix.'survey_nudge_jobs` ENGINE=MyISAM');try{pe_reject(function()use($s){pg_withdraw($s,'DO_NOT_USE');},'QUEUE_TRANSACTION_REQUIRED');pe_equal($before,pg_row($f));}finally{$wpdb->query('ALTER TABLE `'.$wpdb->prefix.'survey_nudge_jobs` ENGINE=InnoDB');}});
pg_case('worker revalidation after mint observes committed B2 before SMTP',function(){ $f=pf_enroll(pf_publish());$shell=pg_shell($f);$before=count($GLOBALS['m0_mail']??array());$observer=new class($shell) extends P\TransitionObserver {private $f;public function __construct($f){$this->f=$f;}public function reached(string $point): void {if($point==='before_delivery_revalidation')pg_withdraw($this->f,'DO_NOT_USE');}};global $wpdb;$intent=pf_intents($f['access']['execution_id'])[0];$job=$wpdb->get_row($wpdb->prepare('SELECT * FROM `'.$wpdb->prefix.'survey_nudge_jobs` WHERE id=%d',$intent['queue_job_id']));pe_assert(EIPSI_Notification_Nudge_Queue_Service::mark_processing($job->id),'No claim');try{$r=(new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock(),$observer))->execute($job);}finally{EIPSI_Notification_Nudge_Queue_Service::release_processing($job->id);}pe_assert(count($GLOBALS['m0_mail']??array())===$before&&pg_row($f)['data_policy']==='DO_NOT_USE','Late SMTP delivery');});
pg_case('anonymous cross-sectional withdrawal uses scoped recovery without requiring email',function(){ $p=pe_publish();$f=pe_runtime()->handle($p['public']);$id=$f['access']['execution_id'];$before=(new P\StudyExecutionRepository(pf_db()))->find($id);$ctx=G\AccessContext::anonymous(pf_db(),$p['public'],$f['token']);$r=pf_owner()->withdrawExecution($id,'DO_NOT_USE','ANON_B2',(int)$before['revision'],$ctx);pe_assert(isset($r['revision'])&&(new G\ExportAdapter(pf_db()))->dataset($p['definition']['study']['logical_id'])['rows']===array(),'Anonymous policy');$out=EIPSI_Privacy_Data_Cleanup_Service::run_study_engine(pf_db(),$id);pe_assert($out['cleanup_state']==='COMPLETE_LOCAL','Anonymous cleanup');$retry=pf_owner()->withdrawExecution($id,'DO_NOT_USE','ANON_B2',(int)$before['revision'],$ctx);pe_equal($r,$retry);});
pg_case('cron cleanup batch recovers pending B2 without requiring HTTP open',function(){ $f=pg_complete(pf_enroll(pf_publish()));pg_withdraw(pg_shell($f),'DO_NOT_USE');(new G\CleanupAdapter(pf_db()))->batch(25);pe_assert(G\Policy::outcome(pf_db(),$f['access']['execution_id'])['cleanup_state']==='COMPLETE_LOCAL','Not processed');});
